function makeTile(type){const sizes={tomato:900,onion:650,blood:180},um=sizes[type],canvas=document.createElement('canvas');canvas.width=canvas.height=type==='blood'?1500:1800;const c=canvas.getContext('2d'),r=rng(type==='blood'?81:type==='onion'?31:9),k=canvas.width/um;c.scale(k,k);c.lineWidth=.65;
 if(type==='tomato'){c.fillStyle='#f6ebd8';c.fillRect(0,0,um,um);const vertex=(col,row)=>{const r=rng(((row%6+6)%6)*71+((col%6+6)%6)*977+13);return[col*150+(r()-.5)*48,row*150+(r()-.5)*48]};for(let row=-1;row<7;row++)for(let col=-1;col<7;col++){const r=rng(((row%6+6)%6)*61+((col%6+6)%6)*733+81),pts=[vertex(col,row),vertex(col+1,row),vertex(col+1,row+1),vertex(col,row+1)],x=pts.reduce((v,p)=>v+p[0],0)/4,y=pts.reduce((v,p)=>v+p[1],0)/4;c.beginPath();pts.forEach(([a,b],i)=>i?c.lineTo(a,b):c.moveTo(a,b));c.closePath();c.fillStyle='rgba(232,174,109,'+(.035+r()*.07)+')';c.fill();c.strokeStyle='#a38d5e7c';c.lineWidth=.7;c.stroke();c.save();c.clip();oval(c,x,y,54,49,'#fffaf550');for(let j=0;j<150;j++){const a=r()*TAU,d=Math.sqrt(r()),px=x+Math.cos(a)*81*d,py=y+Math.sin(a)*77*d;c.lineWidth=.3+r()*.65;c.strokeStyle=r()>.35?'#b9482399':'#df842f99';c.beginPath();c.moveTo(px,py);c.lineTo(px+1+r()*5,py+1+r()*2);c.stroke();if(j%5===0)oval(c,px,py,1.1,.7,'#ca5c2570',null,r()*3)}c.restore()}}

 if(type==='onion'){c.fillStyle='#f0e6ee';c.fillRect(0,0,um,um);for(let row=-1;row<15;row++)for(let col=-1;col<28;col++){const r=rng(((row%13+13)%13)*26+((col%26+26)%26)+133);const x=col*25,y=row*50+((col%2+2)%2)*24,w=24,h=49;c.fillStyle=`rgba(164,122,160,${.05+r()*.08})`;c.fillRect(x,y,w,h);c.strokeStyle='#95718b85';c.lineWidth=.65;c.strokeRect(x,y,w,h);const cx=x+12,cy=y+25,phase=r();if(phase<.72){oval(c,cx+(r()-.5)*4,cy,6.4,8.5,'#9874a16a','#785a8d50');for(let j=0;j<13;j++)oval(c,cx+(r()-.5)*10,cy+(r()-.5)*13,.4,.5,'#6c4c8544');oval(c,cx+1,cy+2,1.6,1.9,'#6f4e8880')}else{c.strokeStyle='#5f367dcc';c.lineWidth=1.1;for(let j=0;j<9;j++){let xx=cx+(r()-.5)*13,yy=cy+(r()-.5)*18;if(phase>=.81&&phase<.87){xx=cx+(j-4)*1.5;yy=cy+(r()-.5)*2}if(phase>=.87){yy=cy+(j%2?10:-10);xx=cx+(r()-.5)*12}c.beginPath();c.moveTo(xx-1,yy-2);c.lineTo(xx+1,yy);c.lineTo(xx-1,yy+2);c.stroke()}if(phase>=.94){oval(c,cx,cy-11,6,5,'#9d7cac44');oval(c,cx,cy+11,6,5,'#9d7cac44');c.strokeStyle='#9c719b8c';c.beginPath();c.moveTo(x+1,cy);c.lineTo(x+w-1,cy);c.stroke()}}}}
 if(type==='blood'){c.fillStyle='#f7eff1';c.fillRect(0,0,um,um);for(let row=0;row<18;row++)for(let col=0;col<18;col++){if(r()<.12)continue;const xx=col*10+(r()-.5)*3.5,yy=row*10+(r()-.5)*3.5,rad=3.5+r()*.5,ry=rad*(.9+r()*.1),rot=r()*3;for(const dx of [-um,0,um])for(const dy of [-um,0,um]){const x=xx+dx,y=yy+dy;if(x< -5||x>um+5||y< -5||y>um+5)continue;const g=c.createRadialGradient(x,y,rad*.1,x,y,rad);g.addColorStop(0,'#f1d7dc');g.addColorStop(.35,'#edcbd2');g.addColorStop(.72,'#cc8198c4');g.addColorStop(1,'#ba738b88');oval(c,x,y,rad,ry,g,'#ad6d851f',rot)}}for(const [x,y] of [[49,59],[137,133]]){oval(c,x,y,6.8,6.2,'#c6bed7cf','#8d7aaf66');for(let j=0;j<3;j++)oval(c,x+(j-1)*2.7,y+(j%2?1.8:-1.4),2.5,3,'#704a8fc9',null,j*.5);for(let j=0;j<25;j++)oval(c,x+(r()-.5)*11,y+(r()-.5)*10,.22,.24,'#7e62928c')}for(let j=0;j<25;j++)oval(c,4+r()*(um-8),4+r()*(um-8),.7,.5,'#9066a49c',null,r()*3)}

 return {canvas,um};
}
function euglena(c,t,seed){c.scale(1+Math.sin(t*1.5)*.035,1-Math.sin(t*1.5)*.06);const r=rng(seed);c.lineWidth=.3;c.beginPath();c.moveTo(-25,0);c.bezierCurveTo(-9,-11,15,-9,25,0);c.bezierCurveTo(15,8,-8,11,-25,0);c.closePath();const g=c.createLinearGradient(0,-10,0,10);g.addColorStop(0,'#67974875');g.addColorStop(.45,'#c8d69b99');g.addColorStop(1,'#537d4677');c.fillStyle=g;c.fill();c.strokeStyle='#52794da3';c.stroke();for(let j=0;j<19;j++){const x=(r()-.5)*36,y=(r()-.5)*10;oval(c,x,y,2.5,1.3,'#517c38b0','#81994470',r()*2)}oval(c,18,-2,1.4,.9,'#ba4c2bd9');oval(c,-3,0,2.6,3,'#d3d4a75c');c.strokeStyle='#6887749c';c.lineWidth=.22;c.beginPath();c.moveTo(24,0);for(let i=1;i<=28;i++)c.lineTo(24+i*.85,Math.sin(i*.23-t*6)*i*.09);c.stroke()}
